ALTER TABLE "service" DROP CONSTRAINT "service_catalog_valid";--> statement-breakpoint
ALTER TABLE "service" ADD CONSTRAINT "service_catalog_valid" CHECK ("service"."catalog_version">0 and (("service"."catalog_kind"='service' and "service"."parent_service_id" is null and "service"."option_label" is null) or ("service"."catalog_kind"='variant' and "service"."parent_service_id" is not null and "service"."option_label" is not null and length(trim("service"."option_label")) between 1 and 80) or ("service"."catalog_kind"='addon' and "service"."parent_service_id" is null and "service"."option_label" is null)));